abstract class Shape2D {
    public abstract double area();
}

abstract class Shape3D {
    public abstract double volume();
}

abstract class Calculator {
    protected List<Object> shapes;

    public Calculator(List<Object> shapes) {
        this.shapes = shapes;
    }

    public abstract double sum();
}

class AreaCalculator extends Calculator {
    public AreaCalculator(List<Object> shapes) {
        super(shapes);
    }

    @Override
    public double sum() {
        double totalArea = 0;
        for (Object shape : shapes) {
            if (shape instanceof Shape2D) {
                totalArea += ((Shape2D) shape).area();
            } else {
                throw new IllegalArgumentException("Invalid Shape: Shape does not implement Shape2D interface");
            }
        }
        return totalArea;
    }
}

class VolumeCalculator extends Calculator {
    public VolumeCalculator(List<Object> shapes) {
        super(shapes);
    }

    @Override
    public double sum() {
        double totalVolume = 0;
        for (Object shape : shapes) {
            if (shape instanceof Shape3D) {
                totalVolume += ((Shape3D) shape).volume();
            } else {
                throw new IllegalArgumentException("Invalid Shape: Shape does not implement Shape3D interface");
            }
        }
        return totalVolume;
    }
}
